<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import { ArrowRight, Check, ChevronDown, ChevronRight, CircleAlert, Copy, Download, FlaskConical, Layers3, Pause, Play, Plus, RotateCcw, SlidersHorizontal, Sparkles, Square, X } from 'lucide-svelte';
  import { calculateMetrics, thresholdMetrics, repeatability, mostProbableLevel, validateRequest } from './domain';
  import { download as saveDownload, errorMessage } from './storage';
  import CodeEditor from './CodeEditor.svelte';
  import type { Dataset, DatasetRow, Project, Request, Session, TypeSafeResponse } from './domain';

  let { projects, datasets, sessions, activeProjectId, mode, liveAvailable, onmodechange, execute, onupdate, experiments = [] }: {
    projects: Project[]; datasets: Dataset[]; sessions: Session[]; activeProjectId: string; mode: 'demo' | 'live';
    liveAvailable: boolean; onmodechange: (mode: 'demo' | 'live') => void;
    execute: (request: Request, repetition?: number) => Promise<{ response: TypeSafeResponse; latency_ms: number }>;
    onupdate: (experiments: any[]) => void; experiments: any[];
  } = $props();

  type ExperimentType = 'evaluation' | 'repeatability' | 'comparison';
  type Task = { id: string; row: DatasetRow; variant_id: string; repetition: number; request: Request; status: string; response?: TypeSafeResponse; latency_ms?: number; started_at?: string; completed_at?: string; error?: string; error_json?: unknown };
  type Variant = { id: string; name: string; session_id: string; version: number; questions: Request['questions']; model: string };
  type Experiment = { id: string; project_id: string; name: string; type: ExperimentType; status: string; created_at: string; completed_at?: string; mode: 'demo' | 'live'; dataset_id: string; dataset_name: string; repeats: number; concurrency: number; variants: Variant[]; tasks: Task[] };

  let records = $state<Experiment[]>([]);
  let selectedId = $state('');
  let activeTab = $state<'experiments' | 'thresholds'>('experiments');
  let filter = $state<'all' | ExperimentType>('all');
  let showModal = $state(false);
  let newName = $state('');
  let newType = $state<ExperimentType>('evaluation');
  let datasetId = $state('');
  let sessionId = $state('');
  let variantSessionId = $state('');
  let model = $state('jev-latest');
  let repeats = $state(20);
  let concurrency = $state(3);
  let rowId = $state('');
  let showRequestPreview = $state(false);
  let previewVariant = $state<'a' | 'b'>('a');
  let formError = $state('');
  let expandedTask = $state('');
  let copiedTask = $state('');
  let copyError = $state('');
  let expandedQuestion = $state('');
  let onlyErrors = $state(false);
  let comparisonThreshold = $state(0.8);
  let low = $state(0.2);
  let high = $state(0.85);
  let labExperimentId = $state('');
  let labQuestionId = $state('');
  let labVariantId = $state('');
  let alive = true;
  const inFlight = new Map<string, Set<string>>();

  const typeNames: Record<ExperimentType, string> = { evaluation: 'Dataset evaluation', repeatability: 'Repeatability test', comparison: 'Variant comparison' };
  const percent = (n: number | null | undefined, digits = 0) => n == null || !Number.isFinite(n) ? '—' : `${(n * 100).toFixed(digits)}%`;
  const number = (n: number | null | undefined, digits = 2) => n == null || !Number.isFinite(n) ? '—' : n.toFixed(digits);
  const clone = <T,>(value: T): T => JSON.parse(JSON.stringify(value));
  const uid = () => crypto.randomUUID();
  const completed = (e: Experiment) => e.tasks.filter(t => t.status === 'success' || t.status === 'error').length;
  const date = (s: string) => new Date(s).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
  const display = (value: unknown) => value == null ? 'No label' : typeof value === 'object' ? JSON.stringify(value) : String(value);
  const answerValue = (answer: any) => answer?.type === 'noul' ? answer.noul >= 0.5 : answer?.type === 'choice' ? answer.choice : answer?.type === 'score' ? mostProbableLevel(answer) : undefined;
  const metricsFor = (tasks: Task[]) => calculateMetrics(tasks.filter(t => t.status === 'success' || t.status === 'error').map(t => ({ row: t.row, response: t.response ?? null })));

  let projectDatasets = $derived(datasets.filter(d => d.project_id === activeProjectId));
  let projectSessions = $derived(sessions.filter(s => s.project_id === activeProjectId));
  let projectRecords = $derived(records.filter(e => e.project_id === activeProjectId));
  let visibleRecords = $derived(projectRecords.filter(e => filter === 'all' || e.type === filter));
  let selected = $derived(projectRecords.find(e => e.id === selectedId));
  let selectedMetrics = $derived(selected ? metricsFor(selected.tasks) : null);
  let selectedDataset = $derived(projectDatasets.find(d => d.id === datasetId));
  let previewRow = $derived(newType === 'repeatability'
    ? selectedDataset?.rows.find(row => row.id === (rowId || selectedDataset?.rows[0]?.id))
    : selectedDataset?.rows[0]);
  let previewSession = $derived(projectSessions.find(session => session.id === (newType === 'comparison' && previewVariant === 'b' ? variantSessionId : sessionId)));
  let requestPreview = $derived(previewRow && previewSession ? {
    state: previewRow.state,
    model: model.trim(),
    questions: previewSession.questions_json,
  } satisfies Request : null);
  let successfulCount = $derived(projectRecords.reduce((sum, e) => sum + e.tasks.filter(t => t.status === 'success').length, 0));
  let finishedCount = $derived(projectRecords.filter(e => e.status === 'completed').length);
  let visibleTasks = $derived(selected?.tasks.filter(t => !onlyErrors || t.status === 'error' || Object.entries(t.row.expected ?? {}).some(([id, expected]) => t.status === 'success' && (!t.response?.answers[id] || String(answerValue(t.response.answers[id])) !== String(expected)))) ?? []);
  let labExperiments = $derived(projectRecords.filter(e => e.status === 'completed' && e.tasks.some(t => t.status === 'success' && Object.entries(t.response?.answers ?? {}).some(([id, a]) => a.type === 'noul' && typeof t.row.expected?.[id] === 'boolean'))));
  let labExperiment = $derived(labExperiments.find(e => e.id === labExperimentId) ?? labExperiments[0]);
  let labVariant = $derived(labExperiment?.variants.find(v => v.id === labVariantId) ?? labExperiment?.variants[0]);
  let labQuestions = $derived([...new Set(labExperiment?.tasks.filter(t => t.variant_id === labVariant?.id && t.status === 'success').flatMap(t => Object.entries(t.response?.answers ?? {}).filter(([id, a]) => a.type === 'noul' && typeof t.row.expected?.[id] === 'boolean').map(([id]) => id)) ?? [])]);
  let labQuestion = $derived(labQuestions.includes(labQuestionId) ? labQuestionId : labQuestions[0]);
  let labSamples = $derived(labExperiment?.tasks.filter(t => t.variant_id === labVariant?.id && t.status === 'success' && typeof t.row.expected?.[labQuestion] === 'boolean' && Number.isFinite(t.response?.answers[labQuestion]?.noul)).map(t => ({ probability: t.response!.answers[labQuestion].noul!, expected: t.row.expected[labQuestion] as boolean })) ?? []);
  let policy = $derived(thresholdMetrics(labSamples, low, high));
  let histogram = $derived(Array.from({ length: 25 }, (_, index) => labSamples.filter(s => Math.min(24, Math.floor(s.probability * 25)) === index).length));
  let maxBin = $derived(Math.max(1, ...histogram));
  let curve = $derived(Array.from({ length: 11 }, (_, index) => { const boundary = 0.5 + index * 0.049; const metrics = thresholdMetrics(labSamples, 1 - boundary, boundary); return { boundary, ...metrics }; }));

  function persist() {
    records = [...records];
    onupdate(clone(records));
  }

  function hydrate() {
    records = clone(experiments).filter((e: any) => Array.isArray(e.tasks) && Array.isArray(e.variants));
    let recovered = false;
    records.forEach(e => {
      if (e.status === 'running') { e.status = 'interrupted'; recovered = true; }
      e.tasks.forEach(t => { if (t.status === 'running') { t.status = 'queued'; recovered = true; } });
    });
    if (recovered) persist();
  }

  onMount(() => { if (experiments.length) hydrate(); });
  $effect(() => { if (experiments.length && !records.length) hydrate(); });

  onDestroy(() => {
    alive = false;
    records.forEach(e => { if (e.status === 'running') e.status = 'interrupted'; });
    persist();
  });

  export function openCreate(type: ExperimentType = 'evaluation', preferredDatasetId?: string) {
    newType = type;
    newName = '';
    const dataset = projectDatasets.find(d => d.id === preferredDatasetId) ?? projectDatasets[0];
    datasetId = dataset?.id ?? '';
    sessionId = projectSessions[0]?.id ?? '';
    variantSessionId = projectSessions[1]?.id ?? '';
    model = projectSessions[0]?.requested_model ?? 'jev-latest';
    rowId = dataset?.rows[0]?.id ?? '';
    previewVariant = 'a';
    showRequestPreview = false;
    formError = '';
    showModal = true;
  }

  function launch() {
    if (mode === 'live' && !liveAvailable) { formError = 'Live API requires a saved API key in Settings in the desktop app.'; return; }
    const dataset = projectDatasets.find(d => d.id === datasetId);
    const session = projectSessions.find(s => s.id === sessionId);
    const second = projectSessions.find(s => s.id === variantSessionId);
    if (!dataset?.rows.length) { formError = 'Choose a dataset with at least one row.'; return; }
    if (!session || !Object.keys(session.questions_json).length) { formError = 'Save a question set with at least one question in Playground first.'; return; }
    if (newType === 'comparison' && (!second || second.id === session.id)) { formError = 'Choose two different saved question sets to compare.'; return; }
    if (!model.trim()) { formError = 'Enter a model name.'; return; }
    const c = Math.min(10, Math.max(1, Math.floor(Number(concurrency) || 1)));
    const count = newType === 'repeatability' ? Math.min(50, Math.max(2, Math.floor(Number(repeats) || 2))) : 1;
    const rows = newType === 'repeatability' ? dataset.rows.filter(r => r.id === (rowId || dataset.rows[0].id)) : dataset.rows;
    if (!rows.length) { formError = 'Select a dataset row to repeat.'; return; }
    const variants: Variant[] = [session, ...(newType === 'comparison' && second ? [second] : [])].map((s, i) => ({ id: uid(), name: newType === 'comparison' ? `${i === 0 ? 'A' : 'B'} · ${s.name} · v${s.version}` : `${s.name} · v${s.version}`, session_id: s.id, version: s.version, questions: clone(s.questions_json), model: model.trim() }));
    const validationErrors = variants.flatMap(variant => validateRequest({ state: rows[0].state, questions: variant.questions, model: variant.model }));
    if (validationErrors.length) { formError = validationErrors.join(' '); return; }
    const tasks: Task[] = rows.flatMap(row => variants.flatMap(variant => Array.from({ length: count }, (_, index) => ({ id: uid(), row: clone(row), variant_id: variant.id, repetition: index + 1, request: { state: clone(row.state), model: variant.model, questions: clone(variant.questions) }, status: 'queued' }))));
    const experiment: Experiment = { id: uid(), project_id: activeProjectId, name: newName.trim() || `${session.name} · ${typeNames[newType].toLowerCase()}`, type: newType, status: 'running', created_at: new Date().toISOString(), mode, dataset_id: dataset.id, dataset_name: dataset.name, repeats: count, concurrency: c, variants, tasks };
    records = [experiment, ...records];
    selectedId = experiment.id;
    activeTab = 'experiments';
    filter = 'all';
    showModal = false;
    persist();
    pump(experiment.id);
  }

  function pump(id: string) {
    const experiment = records.find(e => e.id === id);
    if (!alive || !experiment) return;
    const active = inFlight.get(id) ?? new Set<string>();
    // Final in-flight results also settle a paused run, even if its mode has changed.
    if (['running', 'paused'].includes(experiment.status) && !active.size && !experiment.tasks.some(t => t.status === 'queued' || t.status === 'running')) {
      experiment.status = 'completed';
      experiment.completed_at = new Date().toISOString();
      persist();
      return;
    }
    if (experiment.status !== 'running') return;
    if (experiment.mode !== mode || experiment.mode === 'live' && !liveAvailable) { experiment.status = 'paused'; persist(); return; }
    inFlight.set(id, active);
    while (active.size < experiment.concurrency) {
      const task = experiment.tasks.find(t => t.status === 'queued');
      if (!task) break;
      active.add(task.id);
      task.status = 'running';
      task.started_at = new Date().toISOString();
      const started = performance.now();
      persist();
      execute(clone(task.request), task.repetition).then(result => {
        task.response = clone(result.response);
        task.latency_ms = result.latency_ms;
        task.status = 'success';
      }).catch(error => { task.status = 'error'; task.error = errorMessage(error); task.error_json = error instanceof Error ? { ...error, name: error.name, message: error.message } : error ?? null; task.latency_ms = Math.round(performance.now() - started); }).finally(() => {
        task.completed_at = new Date().toISOString();
        active.delete(task.id);
        persist();
        if (alive) pump(id);
      });
    }
  }

  function pause(e: Experiment) { e.status = 'paused'; persist(); }
  function resume(e: Experiment) {
    if (e.mode !== mode || e.mode === 'live' && !liveAvailable) return;
    e.status = 'running'; persist(); pump(e.id);
  }
  function cancel(e: Experiment) {
    e.status = 'cancelled';
    e.tasks.forEach(t => { if (t.status === 'queued') t.status = 'cancelled'; });
    persist();
  }
  function dialogFocus(node: HTMLElement) {
    const previous = document.activeElement as HTMLElement | null;
    const frame = requestAnimationFrame(() => node.querySelector<HTMLInputElement>('input')?.focus());
    const trap = (event: KeyboardEvent) => {
      if (event.key !== 'Tab') return;
      const controls = [...node.querySelectorAll<HTMLElement>('button:not(:disabled), input:not(:disabled), select:not(:disabled), [tabindex="0"]')];
      const first = controls[0], last = controls[controls.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
    };
    node.addEventListener('keydown', trap);
    return { destroy() { cancelAnimationFrame(frame); node.removeEventListener('keydown', trap); previous?.focus(); } };
  }
  async function copyTaskJSON(task: Task) {
    try { await navigator.clipboard.writeText(JSON.stringify({ request: task.request, response: task.response ?? null, error: task.error_json ?? task.error ?? null }, null, 2)); copiedTask = task.id; copyError = ''; }
    catch { copyError = 'Clipboard unavailable. Select the JSON or use Export.'; }
  }
  async function exportJSON(value: unknown, name: string) {
    await saveDownload(`${name.replace(/[^a-z0-9_-]/gi, '-').toLowerCase()}.json`, JSON.stringify(value, null, 2), 'application/json');
  }
  function repeatStats(e: Experiment, questionId: string) {
    const answers = e.tasks.filter(t => t.status === 'success').map(t => t.response?.answers[questionId]).filter(Boolean);
    const numeric = answers.map(a => a!.type === 'noul' ? a!.noul : a!.type === 'score' ? a!.score : undefined).filter((v): v is number => v !== undefined);
    const counts: Record<string, number> = {};
    answers.forEach(a => { const label = String(answerValue(a)); counts[label] = (counts[label] ?? 0) + 1; });
    const stats = numeric.length ? repeatability(numeric) : null;
    return { stats, count: answers.length, counts, agreement: answers.length ? Math.max(...Object.values(counts)) / answers.length : null, crossings: answers.filter(a => a!.type === 'noul' && a!.noul! >= 0.5).length };
  }
  function variantPolicy(tasks: Task[]) {
    let total = 0, automatic = 0, correct = 0, falseApprovals = 0, falseRejections = 0;
    tasks.filter(task => task.status === 'success').forEach(task => {
      Object.entries(task.row.expected).forEach(([id, expected]) => {
        const answer = task.response?.answers[id];
        if (!answer) return;
        total++;
        const acts = answer.type === 'noul' ? answer.noul! < 1 - comparisonThreshold || answer.noul! > comparisonThreshold : (answer.confidence ?? -1) >= comparisonThreshold;
        if (acts) { automatic++; if (answerValue(answer) === expected) correct++; else if (answer.type === 'noul' && typeof expected === 'boolean') { if (expected) falseRejections++; else falseApprovals++; } }
      });
    });
    return { coverage: total ? automatic / total : null, accuracy: automatic ? correct / automatic : null, falseApprovals, falseRejections };
  }
  const polyline = (key: 'accuracy' | 'coverage') => curve.filter(p => p[key] !== null).map(p => `${40 + (p.boundary - 0.5) / 0.49 * 590},${170 - (p[key] ?? 0) * 140}`).join(' ');
</script>

<svelte:window onkeydown={event => { if (event.key === 'Escape') showModal = false; }} />

<div class="experiments-view">
  <div class="page-heading">
    <h1>Experiments</h1><span class="toolbar-summary">{projectRecords.length} total · {finishedCount} completed · {successfulCount.toLocaleString()} requests</span>
    <label class="execution-mode">Mode<select aria-label="Experiment execution mode" value={mode} onchange={event => onmodechange(event.currentTarget.value as 'demo' | 'live')}><option value="demo">Demo</option><option value="live" disabled={!liveAvailable}>Live API</option></select></label>
    <button class="btn primary" onclick={() => openCreate()}><Plus size={14} /> New experiment</button>
  </div>

  <div class="view-tabs"><button class:active={activeTab === 'experiments'} onclick={() => activeTab = 'experiments'}><FlaskConical size={15} /> Experiments <span>{projectRecords.length}</span></button><button class:active={activeTab === 'thresholds'} onclick={() => activeTab = 'thresholds'}><SlidersHorizontal size={15} /> Threshold lab</button><div class="tab-spacer"></div>{#if mode === 'demo'}<span class="demo-label"><Sparkles size={12} /> Demo mode · simulated responses</span>{/if}</div>

  {#if activeTab === 'experiments'}
    {#if selected}
      <button class="back-link" onclick={() => selectedId = ''}>← All experiments</button>
      <div class="detail-header"><div><div class="detail-kicker">{typeNames[selected.type]} <span>·</span> {selected.dataset_name}</div><h2>{selected.name}</h2><div class="detail-meta"><span class:success={selected.status === 'completed'} class:running={selected.status === 'running'} class="status"><i></i>{selected.status}</span><span>{date(selected.created_at)}</span><span>{selected.mode === 'demo' ? 'Synthetic demo results' : 'Live API results'}</span></div></div><div class="actions"><button class="btn" onclick={() => exportJSON(selected, selected.name)}><Download size={14} /> Export</button>{#if selected.status === 'running'}<button class="btn" onclick={() => pause(selected)}><Pause size={14} /> Pause</button>{:else if selected.status === 'paused' || selected.status === 'interrupted'}<button class="btn primary" disabled={selected.mode !== mode || selected.mode === 'live' && !liveAvailable} title={selected.mode !== mode ? `Switch to ${selected.mode} mode using the Mode selector above` : selected.mode === 'live' && !liveAvailable ? 'Add your API key in Settings in the desktop app' : 'Resume remaining requests'} onclick={() => resume(selected)}><Play size={14} /> Resume</button>{/if}{#if ['running', 'paused', 'interrupted'].includes(selected.status)}<button class="icon-button" aria-label="Cancel experiment" title="Cancel queued requests" onclick={() => cancel(selected)}><Square size={15} /></button>{/if}</div></div>
      {#if selected.status === 'interrupted'}<div class="notice"><CircleAlert size={16} /> This run was interrupted. Its completed results and request snapshots are saved. Resume to continue queued requests.</div>{/if}
      {#if selected.mode !== mode && ['paused', 'interrupted'].includes(selected.status)}<div class="notice">Select {selected.mode === 'live' ? 'Live API' : 'Demo'} in the Mode selector above before resuming this experiment.</div>{/if}
      {#if selected.mode === 'live' && !liveAvailable && ['paused', 'interrupted'].includes(selected.status)}<div class="notice">Live API requires a saved API key in Settings in the desktop app.</div>{/if}
      <div class="run-progress"><div><span>{completed(selected)} of {selected.tasks.length} requests finished</span><span>{selected.tasks.filter(t => t.status === 'error').length} errors · concurrency {selected.concurrency}</span></div><div class="progress-track"><div style:width={`${completed(selected) / Math.max(1, selected.tasks.length) * 100}%`}></div></div>{#if selected.status === 'paused' || selected.status === 'cancelled'}<p>In-flight requests finish and are saved. {selected.status === 'paused' ? 'New requests are paused.' : 'Queued requests were cancelled.'}</p>{/if}</div>
      <div class="metric-grid"><div class="metric-card"><span>Label accuracy</span><strong>{percent(selectedMetrics?.accuracy, 1)}</strong><small>Across completed, labeled answers</small></div><div class="metric-card"><span>Successful requests</span><strong>{selected.tasks.filter(t => t.status === 'success').length}<em> / {selected.tasks.length}</em></strong><small>All questions batched per state</small></div><div class="metric-card"><span>Mean latency</span><strong>{number(selected.tasks.some(t => t.status === 'success') ? selected.tasks.filter(t => t.status === 'success').reduce((sum, t) => sum + (t.latency_ms ?? 0), 0) / selected.tasks.filter(t => t.status === 'success').length : null, 0)}<em> ms</em></strong><small>Includes the complete request</small></div></div>

      {#if selected.type === 'comparison'}
        <div class="comparison-policy"><label for="comparison-cutoff">Automation cutoff <strong>{comparisonThreshold.toFixed(2)}</strong></label><input id="comparison-cutoff" type="range" min="0.5" max="1" step="0.01" bind:value={comparisonThreshold} /><p>Choice / Score confidence ≥ cutoff; Noul P(true) &lt; {number(1 - comparisonThreshold)} or &gt; {number(comparisonThreshold)}.</p></div><div class="variant-grid">{#each selected.variants as variant}{@const variantTasks = selected.tasks.filter(t => t.variant_id === variant.id)}{@const stats = metricsFor(variantTasks)}{@const automation = variantPolicy(variantTasks)}<div class="variant-card"><h3>{variant.name}</h3><div class="variant-stats"><div><strong>{percent(stats.accuracy, 1)}</strong><span>Accuracy</span></div><div><strong>{percent(stats.meanConfidence, 1)}</strong><span>Choice / Score confidence</span></div></div><div class="variant-details"><span>Automatic coverage <b>{percent(automation.coverage, 1)}</b></span><span>Automatic accuracy <b>{percent(automation.accuracy, 1)}</b></span><span>Noul false approvals <b>{automation.falseApprovals}</b></span><span>Noul false rejections <b>{automation.falseRejections}</b></span></div><p>{variant.model} · {Object.keys(variant.questions).length} questions</p></div>{/each}</div>
      {/if}

      {#if selected.type === 'repeatability' && selected.tasks.some(t => t.status === 'success')}
        <div class="panel-section"><div class="section-heading"><h3>Consistency across repetitions</h3><span>Decision boundary: P(true) ≥ 0.50</span></div><div class="repeat-grid">{#each Object.keys(selected.variants[0].questions) as questionId}{@const stats = repeatStats(selected, questionId)}<div class="repeat-card"><span class="primitive">{selected.variants[0].questions[questionId].type}</span><h4>{questionId}</h4>{#if stats.stats}<div class="repeat-numbers"><div><span>Mean</span><strong>{number(stats.stats.mean, 3)}</strong></div><div><span>Min / max</span><strong>{number(stats.stats.min, 3)} / {number(stats.stats.max, 3)}</strong></div><div><span>Std. deviation</span><strong>{number(stats.stats.stdDev, 4)}</strong></div></div>{/if}<div class="agreement"><span>Winning label agreement</span><strong>{percent(stats.agreement)}</strong></div>{#each Object.entries(stats.counts) as [label, count]}<div class="label-frequency"><span>{label}</span><div><i style:width={`${count / Math.max(1, stats.count) * 100}%`}></i></div><strong>{count} / {stats.count}</strong></div>{/each}{#if selected.variants[0].questions[questionId].type === 'noul'}<p>{stats.crossings} / {stats.count} at or above P(true) = 0.50. {stats.crossings > 0 && stats.crossings < stats.count ? 'Decision boundary crossed between repetitions.' : 'No decision boundary crossing.'}</p>{/if}</div>{/each}</div></div>
      {/if}

      <div class="panel-section"><div class="section-heading"><div><h3>Question metrics</h3></div></div>{#if selectedMetrics?.questions.length}<div class="table-scroll"><table class="question-table"><thead><tr><th>Question</th><th>Primitive</th><th>Accuracy</th><th>Precision / recall</th><th>Calibration / error</th><th></th></tr></thead><tbody>{#each selectedMetrics.questions as q}<tr><td class="question-name">{q.questionId}</td><td><span class="primitive">{q.type}</span></td><td>{percent(q.accuracy, 1)}</td><td>{q.type === 'score' ? `Within one: ${percent(q.withinOne)}` : `${percent(q.precision)} / ${percent(q.recall)}`}</td><td>{q.type === 'noul' ? `Brier ${number(q.brierScore, 3)}` : q.type === 'score' ? `MAE ${number(q.mae, 2)}` : `Confidence ${percent(q.meanConfidence)}`}</td><td><button class="icon-button" aria-label={`Details for ${q.questionId}`} onclick={() => expandedQuestion = expandedQuestion === q.questionId ? '' : q.questionId}>{#if expandedQuestion === q.questionId}<ChevronDown size={15} />{:else}<ChevronRight size={15} />{/if}</button></td></tr>{#if expandedQuestion === q.questionId}<tr class="expanded-row"><td colspan="6"><div class="question-extra"><span>{q.correct} correct / {q.total} labeled · {q.missing} missing answers</span>{#if q.f1 !== undefined}<span>F1 {number(q.f1, 3)}</span>{/if}{#if q.type === 'noul'}<span>False-positive rate {percent(q.falsePositiveRate, 1)}</span><span>False-negative rate {percent(q.falseNegativeRate, 1)}</span>{/if}{#if q.perClass}<details><summary>Per-class precision, recall, F1, and support</summary><pre>{JSON.stringify(q.perClass, null, 2)}</pre></details>{/if}{#if q.type === 'score'}<p>Score is a probability-weighted rubric level. It is not an exact continuous measurement.</p>{/if}{#if q.confusionMatrix}<details><summary>Confusion matrix · expected → predicted</summary><pre>{JSON.stringify(q.confusionMatrix, null, 2)}</pre></details>{/if}</div></td></tr>{/if}{/each}</tbody></table></div>{:else}<div class="compact-empty">Metrics appear as requests complete. Add expected labels to your dataset to measure accuracy.</div>{/if}</div>

      <div class="panel-section"><div class="section-heading"><div><h3>Row results <span class="count-pill">{selected.tasks.length}</span></h3></div><label class="checkbox-label"><input type="checkbox" bind:checked={onlyErrors} /> Errors & mismatches</label></div><div class="table-scroll"><table><thead><tr><th>Dataset row</th>{#if selected.type === 'comparison'}<th>Variant</th>{/if}<th>Run</th><th>Status</th><th>Latency</th><th>Model</th><th></th></tr></thead><tbody>{#each visibleTasks as task}<tr><td class="question-name">{task.row.id}</td>{#if selected.type === 'comparison'}<td>{selected.variants.find(v => v.id === task.variant_id)?.name}</td>{/if}<td>#{task.repetition}</td><td><span class="status" class:success={task.status === 'success'} class:failed={task.status === 'error'} class:running={task.status === 'running'}><i></i>{task.status}</span></td><td>{task.latency_ms == null ? '—' : `${Math.round(task.latency_ms)} ms`}</td><td class="mono muted">{task.response?.model ?? '—'}</td><td><button class="icon-button" aria-label={`Expand ${task.row.id} run ${task.repetition}`} onclick={() => expandedTask = expandedTask === task.id ? '' : task.id}>{#if expandedTask === task.id}<ChevronDown size={15} />{:else}<ChevronRight size={15} />{/if}</button></td></tr>{#if expandedTask === task.id}<tr class="expanded-row"><td colspan={selected.type === 'comparison' ? 7 : 6}><div class="row-details"><details open class="result-json"><summary>Request / response JSON</summary><div class="json-actions"><button class="btn" onclick={() => copyTaskJSON(task)}><Copy size={12} />{copiedTask === task.id ? 'Copied' : 'Copy JSON'}</button>{#if copyError}<span>{copyError}</span>{/if}</div><pre>{JSON.stringify({ request: task.request, response: task.response ?? null, error: task.error_json ?? task.error ?? null }, null, 2)}</pre></details>{#if task.error}<div class="error-message"><CircleAlert size={15} />{task.error}</div>{/if}{#each Object.entries(task.response?.answers ?? {}) as [id, answer]}<div class="answer-detail"><div><strong>{id}</strong><span class="primitive">{answer.type}</span></div><div class="answer-labels"><span>Expected <b>{display(task.row.expected?.[id])}</b></span><span>{answer.type === 'noul' ? 'P(true)' : 'Predicted'} <b>{answer.type === 'noul' ? percent(answer.noul, 1) : display(answerValue(answer))}</b></span>{#if answer.type !== 'noul'}<span>Confidence <b>{percent(answer.confidence, 1)}</b></span>{#if answer.type === 'score'}<span>Expected score <b>{number(answer.score, 3)}</b></span>{/if}{/if}</div>{#if answer.probabilities}<div class="distribution">{#each Object.entries(answer.probabilities).sort((a, b) => b[1] - a[1]) as [label, probability]}<div><span>{label}</span><div class="distribution-track"><i style:width={`${probability * 100}%`}></i></div><b>{percent(probability, 1)}</b></div>{/each}</div>{/if}</div>{/each}</div></td></tr>{/if}{/each}</tbody></table>{#if !visibleTasks.length}<div class="compact-empty">No errors or mismatches in the completed results.</div>{/if}</div></div>
    {:else}
      <div class="experiment-toolbar"><div class="filter-buttons">{#each [['all', 'All experiments'], ['evaluation', 'Evaluations'], ['repeatability', 'Repeatability'], ['comparison', 'Comparisons']] as [value, label]}<button class:chosen={filter === value} onclick={() => filter = value as typeof filter}>{label}</button>{/each}</div><span>{visibleRecords.length} experiments</span></div>
      {#if visibleRecords.length}
        <div class="experiment-list">{#each visibleRecords as experiment}{@const stats = metricsFor(experiment.tasks)}<button class="experiment-row" onclick={() => { selectedId = experiment.id; expandedTask = ''; onlyErrors = false; }}><span class="experiment-icon">{#if experiment.type === 'repeatability'}<RotateCcw size={20} />{:else if experiment.type === 'comparison'}<Layers3 size={20} />{:else}<FlaskConical size={20} />{/if}</span><div class="experiment-title"><strong>{experiment.name}</strong><span>{typeNames[experiment.type]} <i>·</i> {experiment.dataset_name}</span></div><div class="list-metric"><strong>{percent(stats.accuracy, 1)}</strong><span>accuracy</span></div><div class="list-metric"><strong>{completed(experiment)} / {experiment.tasks.length}</strong><span>requests</span></div><span class="status" class:success={experiment.status === 'completed'} class:running={experiment.status === 'running'}><i></i>{experiment.status}</span><span class="list-date">{date(experiment.created_at)}</span><ChevronRight size={17} /></button>{/each}</div>
      {:else}
        <div class="empty-experiments"><h2>{projectRecords.length ? 'No matching experiments' : 'No experiments yet'}</h2><p>{projectRecords.length ? 'Change the filter or create an experiment.' : 'Evaluate a dataset, repeat one state, or compare saved question sets.'}</p><button class="btn primary" onclick={() => openCreate()}><Plus size={14} /> New experiment</button></div>
      {/if}

    {/if}
  {:else}
    <div class="lab-intro"><h2>Noul threshold policy</h2></div>
    {#if !labExperiment}
      <div class="threshold-empty"><h3>No labeled Noul results</h3><p>Complete a dataset evaluation with Noul questions and boolean expected labels.</p><button class="btn" onclick={() => openCreate('evaluation')}>Create an evaluation <ArrowRight size={14} /></button></div>
    {:else}
      <div class="lab-selectors"><label>Experiment<select value={labExperiment.id} onchange={e => { labExperimentId = e.currentTarget.value; labQuestionId = ''; labVariantId = ''; }}>{#each labExperiments as e}<option value={e.id}>{e.name}</option>{/each}</select></label><label>Question<select value={labQuestion} onchange={e => labQuestionId = e.currentTarget.value}>{#each labQuestions as q}<option>{q}</option>{/each}</select></label>{#if labExperiment.variants.length > 1}<label>Variant<select value={labVariant?.id} onchange={e => labVariantId = e.currentTarget.value}>{#each labExperiment.variants as v}<option value={v.id}>{v.name}</option>{/each}</select></label>{/if}</div>
      <div class="lab-source"><span class="green-dot"></span> {labSamples.length} labeled responses · {labExperiment.mode === 'demo' ? 'Synthetic demo data — explore the workflow before using live evidence' : 'Completed live experiment'} · Noul output is P(true)</div>
      <div class="threshold-panel"><div class="section-heading"><h3>Decision boundaries</h3><button class="text-button" onclick={() => { low = 0.2; high = 0.85; }}>Reset</button></div><div class="probability-histogram" aria-label="Distribution of observed P(true) values">{#each histogram as count, i}<div class:bar-no={(i + .5) / 25 < low} class:bar-yes={(i + .5) / 25 > high} style:height={`${count / maxBin * 100}%`} title={`${(i / 25).toFixed(2)}–${((i + 1) / 25).toFixed(2)}: ${count} responses`}></div>{/each}</div><div class="decision-track"><span style:width={`${low * 100}%`}>NO</span><span style:width={`${(high - low) * 100}%`}>REVIEW</span><span style:width={`${(1 - high) * 100}%`}>YES</span><i class="boundary-mark" style:left={`${low * 100}%`}></i><i class="boundary-mark" style:left={`${high * 100}%`}></i></div><div class="axis-labels"><span>0.00</span><span>0.25</span><span>0.50</span><span>0.75</span><span>1.00</span></div><div class="slider-grid"><label><span>Automatically reject <b>P(true) &lt; {low.toFixed(2)}</b></span><input type="range" aria-label="Rejection probability threshold" min="0" max="1" step="0.01" value={low} oninput={e => low = Math.min(Number(e.currentTarget.value), high)} /></label><label><span>Automatically approve <b>P(true) &gt; {high.toFixed(2)}</b></span><input type="range" aria-label="Approval probability threshold" min="0" max="1" step="0.01" value={high} oninput={e => high = Math.max(Number(e.currentTarget.value), low)} /></label></div><p>Values from {low.toFixed(2)} through {high.toFixed(2)}, including the boundaries, go to human review.</p></div>
      <div class="metric-grid lab-metrics"><div class="metric-card"><span>Automatic decisions</span><strong>{percent(policy.coverage, 1)}</strong><small>{policy.automatic} labeled responses</small></div><div class="metric-card"><span>Human review</span><strong>{percent(policy.reviewRate, 1)}</strong><small>{policy.review} labeled responses</small></div><div class="metric-card"><span>Automatic decision accuracy</span><strong>{percent(policy.accuracy, 1)}</strong><small>Of responses outside the review band</small></div><div class="metric-card"><span>False approvals / rejections</span><strong>{policy.falseApprovals}<em> / </em>{policy.falseRejections}</strong><small>Compared with expected boolean labels</small></div></div>
      <div class="panel-section curve-panel"><div class="section-heading"><div><h3>Accuracy meets coverage</h3><p>Symmetric boundaries: reject below 1 − threshold, approve above threshold.</p></div><div class="chart-legend"><span><i></i>Accuracy</span><span><i></i>Coverage</span></div></div><svg class="coverage-chart" viewBox="0 0 660 210" role="img" aria-label="Accuracy and automation coverage calculated across probability thresholds">{#each [0, .25, .5, .75, 1] as tick}<line x1="40" x2="630" y1={170 - tick * 140} y2={170 - tick * 140} stroke="var(--border)" stroke-dasharray="3 4" /><text x="28" y={174 - tick * 140} text-anchor="end">{tick * 100}%</text>{/each}{#each [.5, .6, .7, .8, .9, .99] as tick}<text x={40 + (tick - .5) / .49 * 590} y="194" text-anchor="middle">{tick.toFixed(2)}</text>{/each}<polyline points={polyline('coverage')} fill="none" stroke="var(--border-strong)" stroke-width="2.5" /><polyline points={polyline('accuracy')} fill="none" stroke="var(--chart-fill)" stroke-width="2.5" />{#each curve as point}{#if point.accuracy !== null}<circle cx={40 + (point.boundary - .5) / .49 * 590} cy={170 - point.accuracy * 140} r="3" fill="var(--chart-fill)"><title>Threshold {point.boundary.toFixed(2)}: {percent(point.accuracy)} accuracy, {percent(point.coverage)} coverage</title></circle>{/if}{/each}</svg></div>
      <div class="policy-note"><p>Policy metrics apply to the selected labeled results.</p><button class="btn" onclick={() => exportJSON({ experiment_id: labExperiment!.id, variant_id: labVariant!.id, question_id: labQuestion, mode: labExperiment!.mode, primitive: 'noul', reject_below: low, approve_above: high, boundaries: 'inclusive review', labeled_responses: labSamples.length, metrics: policy }, 'jev-threshold-policy')}><Download size={14} /> Export policy</button></div>
    {/if}
  {/if}
</div>

{#if showModal}
  <div class="modal-backdrop" role="presentation" onclick={e => { if (e.target === e.currentTarget) showModal = false; }}>
    <div class="experiment-modal" use:dialogFocus role="dialog" aria-modal="true" aria-labelledby="experiment-modal-title" tabindex="-1"><div class="modal-heading"><button class="icon-button" aria-label="Close experiment dialog" onclick={() => showModal = false}><X size={19} /></button></div><h2 id="experiment-modal-title">New experiment</h2><form onsubmit={e => { e.preventDefault(); launch(); }}><label>Experiment name <span class="optional">optional</span><input bind:value={newName} placeholder="e.g. Resume screening baseline" /></label><label>Experiment type<select bind:value={newType}><option value="evaluation">Dataset evaluation</option><option value="repeatability">Repeatability test</option><option value="comparison">Variant comparison</option></select></label><div class="form-row"><label>Dataset<select bind:value={datasetId} onchange={() => rowId = ''}><option value="" disabled>Select a dataset</option>{#each projectDatasets as d}<option value={d.id}>{d.name} · {d.rows.length} rows</option>{/each}</select></label><label>{newType === 'comparison' ? 'Shared question set · A' : 'Shared question set'}<select bind:value={sessionId}><option value="" disabled>Select a question set</option>{#each projectSessions as s}<option value={s.id}>{s.name} · v{s.version}</option>{/each}</select></label></div><p class="setup-help">Each dataset <code>state</code> is evaluated with the same saved <code>questions</code>. Edit and save question sets in Playground. <code>id</code> and <code>expected</code> stay local; expected labels are used only for evaluation.</p>{#if newType === 'comparison'}<label>Shared question set · B<select bind:value={variantSessionId}><option value="" disabled>Select another question set</option>{#each projectSessions.filter(s => s.id !== sessionId) as s}<option value={s.id}>{s.name} · v{s.version}</option>{/each}</select></label>{/if}{#if newType === 'repeatability'}<div class="form-row"><label>Dataset row<select value={rowId || selectedDataset?.rows[0]?.id || ''} onchange={e => rowId = e.currentTarget.value}>{#each selectedDataset?.rows ?? [] as row}<option value={row.id}>{row.id}</option>{/each}</select></label><label>Repetitions<input type="number" min="2" max="50" bind:value={repeats} /></label></div>{/if}<div class="form-row execution-config"><label>Mode<select aria-label="New experiment execution mode" value={mode} onchange={event => onmodechange(event.currentTarget.value as 'demo' | 'live')}><option value="demo">Demo</option><option value="live" disabled={!liveAvailable}>Live API</option></select></label><label>Model<input bind:value={model} placeholder="jev-latest" /></label><label>Concurrency <span class="optional">1–10</span><input type="number" min="1" max="10" bind:value={concurrency} /></label></div><div class="modal-explanation"><Layers3 size={16} /><span>{newType === 'repeatability' ? `${Math.min(50, Math.max(2, repeats || 2))} requests for one dataset row.` : `${(selectedDataset?.rows.length ?? 0) * (newType === 'comparison' ? 2 : 1)} requests across ${selectedDataset?.rows.length ?? 0} dataset rows.`} All questions for a state are evaluated together.</span></div><details class="request-preview" bind:open={showRequestPreview}>
        <summary>Request preview <span>JSON · read-only</span></summary>
        {#if showRequestPreview}
          <div class="preview-toolbar">
            <span>{previewRow ? `Row: ${previewRow.id}` : 'Select a dataset row'}</span>
            {#if newType === 'comparison'}<label>Preview variant<select bind:value={previewVariant} aria-label="Request preview variant"><option value="a">A</option><option value="b">B</option></select></label>{/if}
          </div>
          {#if requestPreview}<div class="request-preview-editor"><CodeEditor value={JSON.stringify(requestPreview, null, 2)} readonly label="Experiment request preview" /></div>
          {:else}<p class="preview-empty">Select a dataset and saved question set to preview the request.</p>{/if}
        {/if}
      </details>{#if mode === 'demo'}<div class="modal-demo"><Sparkles size={14} /> Demo mode generates synthetic responses. No API calls are made.</div>{:else}<div class="modal-demo">Live API · requests are sent to TypeSafe.</div>{/if}{#if mode === 'live' && !liveAvailable}<div class="notice">Live API requires a saved API key in Settings in the desktop app.</div>{/if}{#if !projectDatasets.length || !projectSessions.length}<div class="notice"><CircleAlert size={15} /><span>{!projectDatasets.length ? 'Add a dataset in Datasets. ' : ''}{!projectSessions.length ? 'Save a question set in Playground.' : ''}</span></div>{/if}{#if formError}<div class="error-message"><CircleAlert size={15} />{formError}</div>{/if}<div class="modal-footer"><button class="btn" type="button" onclick={() => showModal = false}>Cancel</button><button class="btn primary" type="submit" disabled={!projectDatasets.length || !projectSessions.length || mode === 'live' && !liveAvailable}><Play size={14} /> Run</button></div></form></div>
  </div>
{/if}

<style>
  .experiments-view{max-width:1360px;margin:0 auto;padding:30px 36px 48px;color:var(--text-primary)}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:29px}h1{font-size:29px;line-height:1.25;font-weight:570;letter-spacing:-1px;margin:10px 0 7px}h2{font-size:24px;font-weight:560;letter-spacing:-.65px;margin:0}h3{font-size:13px;font-weight:620;margin:0}p{font-size:12px;line-height:1.65;color:var(--text-muted);margin:0}.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;white-space:nowrap}.view-tabs{display:flex;align-items:center;gap:25px;border-bottom:1px solid var(--border);margin-bottom:23px;height:43px}.view-tabs>button{border:0;background:none;align-self:stretch;display:flex;align-items:center;gap:7px;color:var(--text-muted);font-size:11px;padding:0;position:relative}.view-tabs>button.active{color:var(--control);font-weight:600}.view-tabs>button.active:after{content:'';position:absolute;bottom:-1px;left:0;right:0;background:var(--control);height:2px}.view-tabs>button>span,.count-pill{font-size:9px;border:1px solid var(--border);border-radius:4px;padding:0 4px;line-height:15px;background:var(--canvas);color:var(--text-muted)}.tab-spacer{flex:1}.demo-label{display:flex;align-items:center;gap:5px;font-size:9px;color:var(--text-muted)}.experiment-toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:16px}.experiment-toolbar>span{font-size:10px;color:var(--text-muted)}.filter-buttons{display:flex;gap:4px}.filter-buttons button{border:1px solid transparent;background:none;border-radius:5px;padding:6px 10px;color:var(--text-muted);font-size:10px}.filter-buttons button.chosen{background:var(--surface);border-color:var(--border);color:var(--text-primary);box-shadow:0 1px 2px var(--shadow)}.empty-experiments{border:1px solid var(--border);border-radius:10px;background:var(--surface);display:flex;flex-direction:column;align-items:center;text-align:center;padding:35px 25px 31